// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title NGODonation - Ultimate Edition
 * @author BlockXint Engineering Team
 * @notice Production-grade donation platform with comprehensive features, zero external dependencies
 * @dev Single-file implementation with inline security patterns, refunds, milestones, and role-based access
 */
contract NGODonation {

    // =============================================================
    // CUSTOM ERRORS (Gas Efficient)
    // =============================================================
    error NotOwner();
    error NotAuthorized();
    error ZeroAddress();
    error InvalidAmount();
    error Paused();
    error NotPaused();
    error ReentrantCall();
    error CampaignDoesNotExist();
    error CampaignNotActive();
    error CampaignExpired();
    error CampaignAlreadyClosed();
    error InsufficientBalance();
    error TransferFailed();
    error RefundNotAllowed();
    error GoalExceeded();
    error WithdrawalTimelockActive();
    error DailyLimitExceeded();
    error InvalidMilestone();
    error RoleAlreadyGranted();
    error RoleNotGranted();

    // =============================================================
    // INLINE OWNABLE PATTERN
    // =============================================================
    address private _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner() {
        if (msg.sender != _owner) revert NotOwner();
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    // =============================================================
    // INLINE PAUSABLE PATTERN
    // =============================================================
    bool private _paused;

    event PausedState(bool isPaused);

    modifier whenNotPaused() {
        if (_paused) revert Paused();
        _;
    }

    modifier whenPaused() {
        if (!_paused) revert NotPaused();
        _;
    }

    function paused() public view returns (bool) {
        return _paused;
    }

    function pause() external onlyOwner whenNotPaused {
        _paused = true;
        emit PausedState(true);
    }

    function unpause() external onlyOwner whenPaused {
        _paused = false;
        emit PausedState(false);
    }

    // =============================================================
    // INLINE REENTRANCY GUARD PATTERN
    // =============================================================
    uint256 private _reentrancyStatus;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    modifier nonReentrant() {
        if (_reentrancyStatus == _ENTERED) revert ReentrantCall();
        _reentrancyStatus = _ENTERED;
        _;
        _reentrancyStatus = _NOT_ENTERED;
    }

    // =============================================================
    // INLINE ROLE-BASED ACCESS CONTROL
    // =============================================================
    bytes32 private constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 private constant CAMPAIGN_MANAGER_ROLE = keccak256("CAMPAIGN_MANAGER_ROLE");
    bytes32 private constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");

    mapping(bytes32 => mapping(address => bool)) private _roles;

    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);

    modifier onlyRole(bytes32 role) {
        if (!hasRole(role, msg.sender) && msg.sender != _owner) revert NotAuthorized();
        _;
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role][account];
    }

    function grantRole(bytes32 role, address account) external onlyOwner {
        if (account == address(0)) revert ZeroAddress();
        if (_roles[role][account]) revert RoleAlreadyGranted();
        _roles[role][account] = true;
        emit RoleGranted(role, account, msg.sender);
    }

    function revokeRole(bytes32 role, address account) external onlyOwner {
        if (!_roles[role][account]) revert RoleNotGranted();
        _roles[role][account] = false;
        emit RoleRevoked(role, account, msg.sender);
    }

    // =============================================================
    // ENUMS & STRUCTS
    // =============================================================
    enum CampaignStatus { Active, Paused, Completed, Cancelled }

    struct Campaign {
        uint256 id;
        string name;
        string metadataURI;
        address payable beneficiary;
        uint256 goal;
        uint256 minDonation;
        uint256 maxCap;
        uint256 totalRaised;
        uint256 totalWithdrawn;
        uint256 createdAt;
        uint256 expiresAt;
        uint256 lastWithdrawalAt;
        CampaignStatus status;
        bool refundable;
        bool hasMaxCap;
        uint8 platformFeePercent;
    }

    struct Milestone {
        uint256 targetAmount;
        string description;
        bool reached;
        uint256 reachedAt;
    }

    struct Donation {
        address donor;
        uint256 amount;
        uint256 timestamp;
        string message;
        bool refunded;
    }

    struct DonorInfo {
        uint256 totalDonated;
        uint256 donationCount;
        uint256 lastDonationAt;
    }

    // =============================================================
    // STATE VARIABLES
    // =============================================================
    uint256 private _campaignIdCounter;
    uint256 public defaultPlatformFeePercent = 2;
    uint256 public constant MAX_PLATFORM_FEE = 5;
    uint256 public constant WITHDRAWAL_TIMELOCK = 1 days;
    uint256 public dailyWithdrawalLimit = 100 ether;
    uint256 public defaultMinDonation = 0.001 ether;

    address payable public feeCollector;
    uint256 public totalFeesCollected;

    mapping(uint256 => Campaign) private _campaigns;
    mapping(uint256 => Milestone[]) private _milestones;
    mapping(uint256 => Donation[]) private _donations;
    mapping(uint256 => mapping(address => DonorInfo)) private _donorInfo;
    mapping(address => uint256[]) private _userCampaigns; // campaigns user donated to

    // Emergency withdrawal tracking
    mapping(uint256 => uint256) private _dailyWithdrawn;
    mapping(uint256 => uint256) private _lastWithdrawalDay;

    // =============================================================
    // EVENTS
    // =============================================================
    event CampaignCreated(
        uint256 indexed campaignId, 
        address indexed beneficiary, 
        uint256 goal, 
        string name
    );
    event DonationReceived(
        uint256 indexed campaignId, 
        address indexed donor, 
        uint256 amount, 
        string message
    );
    event FundsWithdrawn(
        uint256 indexed campaignId, 
        address indexed beneficiary, 
        uint256 amount
    );
    event CampaignClosed(uint256 indexed campaignId);
    event CampaignStatusChanged(uint256 indexed campaignId, CampaignStatus newStatus);
    event MilestoneAdded(uint256 indexed campaignId, uint256 targetAmount, string description);
    event MilestoneReached(uint256 indexed campaignId, uint256 milestoneIndex, uint256 amount);
    event RefundIssued(uint256 indexed campaignId, address indexed donor, uint256 amount);
    event PlatformFeeUpdated(uint256 newFeePercent);
    event FeeCollectorUpdated(address indexed newCollector);
    event WithdrawalLimitUpdated(uint256 newLimit);
    event EmergencyAction(uint256 indexed campaignId, string action, address indexed initiator);

    // =============================================================
    // CONSTRUCTOR
    // =============================================================
    constructor() {
        _owner = msg.sender;
        _reentrancyStatus = _NOT_ENTERED;
        feeCollector = payable(msg.sender);

        // Grant all roles to deployer
        _roles[ADMIN_ROLE][msg.sender] = true;
        _roles[CAMPAIGN_MANAGER_ROLE][msg.sender] = true;
        _roles[AUDITOR_ROLE][msg.sender] = true;

        emit OwnershipTransferred(address(0), msg.sender);
    }

    // =============================================================
    // CORE CAMPAIGN FUNCTIONS
    // =============================================================

    /**
     * @notice Creates a new donation campaign
     * @param name Campaign name
     * @param metadataURI IPFS/Arweave URI for campaign details
     * @param beneficiary Address that can withdraw funds
     * @param goal Fundraising goal in wei
     * @return campaignId The ID of the newly created campaign
     */
    function createCampaign(
        string calldata name,
        string calldata metadataURI,
        address payable beneficiary,
        uint256 goal
    ) external onlyRole(CAMPAIGN_MANAGER_ROLE) returns (uint256 campaignId) {
        if (beneficiary == address(0)) revert ZeroAddress();
        if (goal == 0) revert InvalidAmount();

        _campaignIdCounter++;
        campaignId = _campaignIdCounter;

        _campaigns[campaignId] = Campaign({
            id: campaignId,
            name: name,
            metadataURI: metadataURI,
            beneficiary: beneficiary,
            goal: goal,
            minDonation: defaultMinDonation,
            maxCap: 0,
            totalRaised: 0,
            totalWithdrawn: 0,
            createdAt: block.timestamp,
            expiresAt: 0,
            lastWithdrawalAt: 0,
            status: CampaignStatus.Active,
            refundable: false,
            hasMaxCap: false,
            platformFeePercent: uint8(defaultPlatformFeePercent)
        });

        emit CampaignCreated(campaignId, beneficiary, goal, name);
    }

    /**
     * @notice Extended campaign creation with advanced options
     */
    function createCampaignAdvanced(
        string calldata name,
        string calldata metadataURI,
        address payable beneficiary,
        uint256 goal,
        uint256 duration,
        uint256 maxCap,
        bool refundable,
        uint256 minDonation
    ) external onlyRole(CAMPAIGN_MANAGER_ROLE) returns (uint256 campaignId) {
        if (beneficiary == address(0)) revert ZeroAddress();
        if (goal == 0) revert InvalidAmount();
        if (maxCap > 0 && maxCap < goal) revert InvalidAmount();
        if (minDonation == 0) minDonation = defaultMinDonation;

        _campaignIdCounter++;
        campaignId = _campaignIdCounter;
        uint256 expiresAt = duration > 0 ? block.timestamp + duration : 0;

        _campaigns[campaignId] = Campaign({
            id: campaignId,
            name: name,
            metadataURI: metadataURI,
            beneficiary: beneficiary,
            goal: goal,
            minDonation: minDonation,
            maxCap: maxCap,
            totalRaised: 0,
            totalWithdrawn: 0,
            createdAt: block.timestamp,
            expiresAt: expiresAt,
            lastWithdrawalAt: 0,
            status: CampaignStatus.Active,
            refundable: refundable,
            hasMaxCap: maxCap > 0,
            platformFeePercent: uint8(defaultPlatformFeePercent)
        });

        emit CampaignCreated(campaignId, beneficiary, goal, name);
    }

    /**
     * @notice Add milestones to track campaign progress
     */
    function addMilestones(
        uint256 campaignId,
        uint256[] calldata amounts,
        string[] calldata descriptions
    ) external onlyRole(CAMPAIGN_MANAGER_ROLE) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (amounts.length != descriptions.length || amounts.length == 0) revert InvalidMilestone();

        for (uint256 i = 0; i < amounts.length; i++) {
            if (amounts[i] == 0) revert InvalidAmount();
            _milestones[campaignId].push(Milestone({
                targetAmount: amounts[i],
                description: descriptions[i],
                reached: false,
                reachedAt: 0
            }));
            emit MilestoneAdded(campaignId, amounts[i], descriptions[i]);
        }
    }

    // =============================================================
    // DONATION FUNCTIONS
    // =============================================================

    /**
     * @notice Donate ETH to a campaign
     * @param campaignId Campaign to donate to
     * @param message Optional message from donor
     */
    function donate(uint256 campaignId, string calldata message) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
    {
        Campaign storage campaign = _campaigns[campaignId];

        // Validation
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (campaign.status != CampaignStatus.Active) revert CampaignNotActive();
        if (campaign.expiresAt > 0 && block.timestamp > campaign.expiresAt) revert CampaignExpired();
        if (msg.value < campaign.minDonation) revert InvalidAmount();

        // Check max cap
        if (campaign.hasMaxCap && campaign.totalRaised + msg.value > campaign.maxCap) {
            revert GoalExceeded();
        }

        // Update campaign
        campaign.totalRaised += msg.value;

        // Update donor info
        DonorInfo storage donorInfo = _donorInfo[campaignId][msg.sender];
        if (donorInfo.donationCount == 0) {
            _userCampaigns[msg.sender].push(campaignId);
        }
        donorInfo.totalDonated += msg.value;
        donorInfo.donationCount++;
        donorInfo.lastDonationAt = block.timestamp;

        // Record donation
        _donations[campaignId].push(Donation({
            donor: msg.sender,
            amount: msg.value,
            timestamp: block.timestamp,
            message: message,
            refunded: false
        }));

        // Check and update milestones
        _checkMilestones(campaignId);

        emit DonationReceived(campaignId, msg.sender, msg.value, message);
    }

    // =============================================================
    // WITHDRAWAL FUNCTIONS
    // =============================================================

    /**
     * @notice Beneficiary withdraws funds with timelock and daily limits
     * @param campaignId Campaign to withdraw from
     * @param amount Amount to withdraw in wei
     */
    function withdraw(uint256 campaignId, uint256 amount) external nonReentrant {
        Campaign storage campaign = _campaigns[campaignId];

        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (msg.sender != campaign.beneficiary) revert NotAuthorized();
        if (amount == 0) revert InvalidAmount();

        // Timelock check (except first withdrawal)
        if (campaign.lastWithdrawalAt > 0) {
            if (block.timestamp < campaign.lastWithdrawalAt + WITHDRAWAL_TIMELOCK) {
                revert WithdrawalTimelockActive();
            }
        }

        // Daily limit check
        uint256 currentDay = block.timestamp / 1 days;
        if (_lastWithdrawalDay[campaignId] != currentDay) {
            _dailyWithdrawn[campaignId] = 0;
            _lastWithdrawalDay[campaignId] = currentDay;
        }

        if (_dailyWithdrawn[campaignId] + amount > dailyWithdrawalLimit) {
            revert DailyLimitExceeded();
        }

        // Balance check
        uint256 availableBalance = campaign.totalRaised - campaign.totalWithdrawn;
        if (amount > availableBalance) revert InsufficientBalance();

        // Calculate fee
        uint256 fee = (amount * campaign.platformFeePercent) / 100;
        uint256 netAmount = amount - fee;

        // Update state
        campaign.totalWithdrawn += amount;
        campaign.lastWithdrawalAt = block.timestamp;
        _dailyWithdrawn[campaignId] += amount;
        totalFeesCollected += fee;

        // Transfer funds
        (bool success1, ) = campaign.beneficiary.call{value: netAmount}("");
        if (!success1) revert TransferFailed();

        if (fee > 0) {
            (bool success2, ) = feeCollector.call{value: fee}("");
            if (!success2) revert TransferFailed();
        }

        emit FundsWithdrawn(campaignId, campaign.beneficiary, netAmount);
    }

    /**
     * @notice Emergency withdrawal for completed/cancelled campaigns (no limits)
     */
    function emergencyWithdraw(uint256 campaignId) external nonReentrant {
        Campaign storage campaign = _campaigns[campaignId];

        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (msg.sender != campaign.beneficiary) revert NotAuthorized();

        // Only allow for non-active campaigns
        if (campaign.status == CampaignStatus.Active) revert CampaignNotActive();

        uint256 availableBalance = campaign.totalRaised - campaign.totalWithdrawn;
        if (availableBalance == 0) revert InsufficientBalance();

        uint256 fee = (availableBalance * campaign.platformFeePercent) / 100;
        uint256 netAmount = availableBalance - fee;

        campaign.totalWithdrawn += availableBalance;
        totalFeesCollected += fee;

        (bool success1, ) = campaign.beneficiary.call{value: netAmount}("");
        if (!success1) revert TransferFailed();

        if (fee > 0) {
            (bool success2, ) = feeCollector.call{value: fee}("");
            if (!success2) revert TransferFailed();
        }

        emit EmergencyAction(campaignId, "Emergency Withdrawal", msg.sender);
        emit FundsWithdrawn(campaignId, campaign.beneficiary, netAmount);
    }

    // =============================================================
    // REFUND FUNCTIONS
    // =============================================================

    /**
     * @notice Request refund if campaign is refundable and conditions met
     */
    function requestRefund(uint256 campaignId) external nonReentrant {
        Campaign storage campaign = _campaigns[campaignId];

        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (!campaign.refundable) revert RefundNotAllowed();

        // Check refund conditions
        bool canRefund = (
            (campaign.expiresAt > 0 && 
             block.timestamp > campaign.expiresAt && 
             campaign.totalRaised < campaign.goal) ||
            campaign.status == CampaignStatus.Cancelled
        );

        if (!canRefund) revert RefundNotAllowed();

        DonorInfo storage donorInfo = _donorInfo[campaignId][msg.sender];
        uint256 refundAmount = donorInfo.totalDonated;

        if (refundAmount == 0) revert InvalidAmount();

        // Update state
        donorInfo.totalDonated = 0;
        campaign.totalRaised -= refundAmount;

        // Mark donations as refunded
        Donation[] storage donations = _donations[campaignId];
        for (uint256 i = 0; i < donations.length; i++) {
            if (donations[i].donor == msg.sender && !donations[i].refunded) {
                donations[i].refunded = true;
            }
        }

        // Transfer refund
        (bool success, ) = msg.sender.call{value: refundAmount}("");
        if (!success) revert TransferFailed();

        emit RefundIssued(campaignId, msg.sender, refundAmount);
    }

    /**
     * @notice Batch refund processing by admin (for cancelled campaigns)
     */
    function batchRefund(uint256 campaignId, address[] calldata donors) 
        external 
        onlyRole(ADMIN_ROLE) 
        nonReentrant 
    {
        Campaign storage campaign = _campaigns[campaignId];

        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (!campaign.refundable || campaign.status != CampaignStatus.Cancelled) {
            revert RefundNotAllowed();
        }

        for (uint256 i = 0; i < donors.length; i++) {
            address donor = donors[i];
            DonorInfo storage donorInfo = _donorInfo[campaignId][donor];
            uint256 refundAmount = donorInfo.totalDonated;

            if (refundAmount > 0) {
                donorInfo.totalDonated = 0;
                campaign.totalRaised -= refundAmount;

                (bool success, ) = donor.call{value: refundAmount}("");
                if (success) {
                    emit RefundIssued(campaignId, donor, refundAmount);
                }
            }
        }
    }

    // =============================================================
    // CAMPAIGN MANAGEMENT
    // =============================================================

    /**
     * @notice Close a campaign (owner or beneficiary)
     */
    function closeCampaign(uint256 campaignId) external {
        Campaign storage campaign = _campaigns[campaignId];

        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (msg.sender != _owner && 
            msg.sender != campaign.beneficiary && 
            !hasRole(CAMPAIGN_MANAGER_ROLE, msg.sender)) {
            revert NotAuthorized();
        }
        if (campaign.status == CampaignStatus.Completed || 
            campaign.status == CampaignStatus.Cancelled) {
            revert CampaignAlreadyClosed();
        }

        campaign.status = CampaignStatus.Completed;
        emit CampaignClosed(campaignId);
        emit CampaignStatusChanged(campaignId, CampaignStatus.Completed);
    }

    function pauseCampaign(uint256 campaignId) external onlyRole(ADMIN_ROLE) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        _campaigns[campaignId].status = CampaignStatus.Paused;
        emit CampaignStatusChanged(campaignId, CampaignStatus.Paused);
    }

    function resumeCampaign(uint256 campaignId) external onlyRole(ADMIN_ROLE) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        Campaign storage campaign = _campaigns[campaignId];
        if (campaign.expiresAt > 0 && block.timestamp > campaign.expiresAt) {
            revert CampaignExpired();
        }
        campaign.status = CampaignStatus.Active;
        emit CampaignStatusChanged(campaignId, CampaignStatus.Active);
    }

    function cancelCampaign(uint256 campaignId) external onlyRole(ADMIN_ROLE) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        _campaigns[campaignId].status = CampaignStatus.Cancelled;
        emit CampaignStatusChanged(campaignId, CampaignStatus.Cancelled);
    }

    /**
     * @notice Update campaign metadata
     */
    function updateCampaignMetadata(uint256 campaignId, string calldata newMetadataURI) 
        external 
        onlyRole(CAMPAIGN_MANAGER_ROLE) 
    {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        _campaigns[campaignId].metadataURI = newMetadataURI;
    }

    // =============================================================
    // ADMIN FUNCTIONS
    // =============================================================

    function setPlatformFee(uint256 newFeePercent) external onlyRole(ADMIN_ROLE) {
        if (newFeePercent > MAX_PLATFORM_FEE) revert InvalidAmount();
        defaultPlatformFeePercent = newFeePercent;
        emit PlatformFeeUpdated(newFeePercent);
    }

    function setFeeCollector(address payable newCollector) external onlyRole(ADMIN_ROLE) {
        if (newCollector == address(0)) revert ZeroAddress();
        feeCollector = newCollector;
        emit FeeCollectorUpdated(newCollector);
    }

    function setWithdrawalLimit(uint256 newLimit) external onlyRole(ADMIN_ROLE) {
        if (newLimit == 0) revert InvalidAmount();
        dailyWithdrawalLimit = newLimit;
        emit WithdrawalLimitUpdated(newLimit);
    }

    function setDefaultMinDonation(uint256 newMin) external onlyRole(ADMIN_ROLE) {
        if (newMin == 0) revert InvalidAmount();
        defaultMinDonation = newMin;
    }

    /**
     * @notice Update specific campaign's fee (for special cases)
     */
    function setCampaignFee(uint256 campaignId, uint8 feePercent) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        if (feePercent > MAX_PLATFORM_FEE) revert InvalidAmount();
        _campaigns[campaignId].platformFeePercent = feePercent;
    }

    // =============================================================
    // VIEW FUNCTIONS
    // =============================================================

    function getCampaign(uint256 campaignId) 
        external 
        view 
        returns (
            uint256 id,
            string memory name,
            string memory metadataURI,
            address payable beneficiary,
            uint256 goal,
            uint256 totalRaised,
            uint256 totalWithdrawn,
            CampaignStatus status
        ) 
    {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        Campaign storage c = _campaigns[campaignId];
        return (
            c.id,
            c.name,
            c.metadataURI,
            c.beneficiary,
            c.goal,
            c.totalRaised,
            c.totalWithdrawn,
            c.status
        );
    }

    function getCampaignDetails(uint256 campaignId) external view returns (Campaign memory) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        return _campaigns[campaignId];
    }

    function getMilestones(uint256 campaignId) external view returns (Milestone[] memory) {
        return _milestones[campaignId];
    }

    function getDonations(uint256 campaignId) external view returns (Donation[] memory) {
        return _donations[campaignId];
    }

    function getDonorInfo(uint256 campaignId, address donor) 
        external 
        view 
        returns (DonorInfo memory) 
    {
        return _donorInfo[campaignId][donor];
    }

    function getUserCampaigns(address user) external view returns (uint256[] memory) {
        return _userCampaigns[user];
    }

    function campaignCount() external view returns (uint256) {
        return _campaignIdCounter;
    }

    function donorTotal(uint256 campaignId, address donor) external view returns (uint256) {
        return _donorInfo[campaignId][donor].totalDonated;
    }

    function campaignRaised(uint256 campaignId) external view returns (uint256) {
        if (!_campaignExists(campaignId)) revert CampaignDoesNotExist();
        return _campaigns[campaignId].totalRaised;
    }

    function getAvailableBalance(uint256 campaignId) external view returns (uint256) {
        Campaign storage campaign = _campaigns[campaignId];
        return campaign.totalRaised - campaign.totalWithdrawn;
    }

    function canWithdraw(uint256 campaignId) external view returns (bool) {
        Campaign storage campaign = _campaigns[campaignId];
        if (campaign.lastWithdrawalAt == 0) return true;
        return block.timestamp >= campaign.lastWithdrawalAt + WITHDRAWAL_TIMELOCK;
    }

    function getRemainingDailyLimit(uint256 campaignId) external view returns (uint256) {
        uint256 currentDay = block.timestamp / 1 days;
        if (_lastWithdrawalDay[campaignId] != currentDay) {
            return dailyWithdrawalLimit;
        }
        return dailyWithdrawalLimit - _dailyWithdrawn[campaignId];
    }

    function getDonationCount(uint256 campaignId) external view returns (uint256) {
        return _donations[campaignId].length;
    }

    function getTotalDonors(uint256 campaignId) external view returns (uint256) {
        Donation[] storage donations = _donations[campaignId];
        uint256 uniqueDonors = 0;

        // Note: This is gas-intensive, consider off-chain calculation for production
        for (uint256 i = 0; i < donations.length; i++) {
            address donor = donations[i].donor;
            bool isUnique = true;
            for (uint256 j = 0; j < i; j++) {
                if (donations[j].donor == donor) {
                    isUnique = false;
                    break;
                }
            }
            if (isUnique) uniqueDonors++;
        }
        return uniqueDonors;
    }

    // =============================================================
    // INTERNAL HELPER FUNCTIONS
    // =============================================================

    function _campaignExists(uint256 campaignId) internal view returns (bool) {
        return campaignId > 0 && campaignId <= _campaignIdCounter;
    }

    function _checkMilestones(uint256 campaignId) internal {
        Campaign storage campaign = _campaigns[campaignId];
        Milestone[] storage milestones = _milestones[campaignId];

        for (uint256 i = 0; i < milestones.length; i++) {
            if (!milestones[i].reached && 
                campaign.totalRaised >= milestones[i].targetAmount) {
                milestones[i].reached = true;
                milestones[i].reachedAt = block.timestamp;
                emit MilestoneReached(campaignId, i, milestones[i].targetAmount);
            }
        }
    }

    // =============================================================
    // EMERGENCY & RECOVERY
    // =============================================================

    /**
     * @notice Emergency pause all donations (keeps withdrawals active)
     */
    function emergencyPause() external onlyRole(ADMIN_ROLE) {
        if (_paused) revert Paused();
        _paused = true;
        emit PausedState(true);
        emit EmergencyAction(0, "Emergency Pause Activated", msg.sender);
    }

    /**
     * @notice Recover accidentally sent ETH (not part of any campaign)
     */
    function recoverExcessETH() external onlyOwner nonReentrant {
        uint256 totalCampaignBalances = 0;
        for (uint256 i = 1; i <= _campaignIdCounter; i++) {
            Campaign storage campaign = _campaigns[i];
            totalCampaignBalances += (campaign.totalRaised - campaign.totalWithdrawn);
        }

        uint256 excess = address(this).balance - totalCampaignBalances;
        if (excess > 0) {
            (bool success, ) = _owner.call{value: excess}("");
            if (!success) revert TransferFailed();
        }
    }

    // =============================================================
    // FALLBACK & RECEIVE
    // =============================================================

    receive() external payable {
        revert("Use donate() function");
    }

    fallback() external payable {
        revert("Use donate() function");
    }
}
